static bool cxusb_medion_check_altsetting ( struct usb_host_interface * as ) { unsigned int ctr ; for ( ctr = 0 ; ctr < as -> desc . bNumEndpoints ; ctr ++ ) { if ( as -> endpoint [ ctr ] . desc . bEndpointAddress & USB_DIR_IN && ( ( as -> endpoint [ ctr ] . desc . bmAttributes & USB_ENDPOINT_XFERTYPE_MASK ) == USB_ENDPOINT_XFER_ISOC ) ) { return true ; } break ; } return false ; } 